sm mb-4 dc-scoring-progress-card"><div class="card-body"><div class="dc-progress-heading"><span class="dc-progress-medallion">◎</span><div><small class="dc-progress-eyebrow">ACTIVE SCORING SHEET</small><strong>Category progress</strong></div><span class="dc-progress-count" id="dcJudgeProgress"><?=$completed?> / <?=$required?></span></div><div class="progress mt-3"><div id="dcJudgeProgressBar" class="progress-bar bg-success" style="width:<?=$required?round($completed/$required*100):0?>%"></div></div></div></section><?php if(!$entries):?><section class="dc-empty-roster" role="status"><div class="dc-waiting-visual"><span class="dc-waiting-ring"></span><span class="dc-waiting-number">#</span></div><div class="dc-waiting-copy"><small>STANDBY MODE</small><h2>Waiting for the competition roster</h2><p>The scoring desk is preparing this category. Your official scoring sheet will appear here as soon as the competitors are confirmed.</p><span class="dc-waiting-status"><i></i> Secure judge session active</span></div><button type="button" class="btn dc-refresh-button" onclick="location.reload()"><span>↻</span> Refresh roster</button></section><?php else:?><form method="post" id="dcJudgeScoreForm" data-dc-judge-live><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><?php foreach($entries as $entry):?><article class="card entry-card mb-3"><div class="card-body p-3 p-md-4"><div class="d-flex align-items-baseline gap-3 mb-3"><span class="display-6 fw-bold text-primary">#<?=(int)$entry['bib_number']?></span><h2 class="h4 mb-0"><?=e($entry['display_name'])?></h2></div><div class="criteria-grid"><?php foreach($criteria as $criterion):$v=$values[$entry['id']][$criterion['id']]??'';?><div class="score-box"><label class="form-label"><?=e($criterion['criterion_name'])?> <span class="text-muted">/ <?=e(rtrim(rtrim(number_format((float)$criterion['maximum_poin